const j = $json;
const p = j.profile || {};
const list = (a) => (Array.isArray(a) && a.length ? a.join(', ') : 'non précisé');
const SYSTEM = "Tu es un expert du recrutement en France qui rédige des lettres de motivation percutantes.\nRègles :\n- Lettre en français, 220 à 320 mots, ton professionnel, sincère et dynamique (pas de formules creuses).\n- Structure : accroche liée à l'entreprise ou au poste, 2 expériences/compétences du CV reliées précisément aux besoins de l'offre, motivation pour CETTE entreprise, conclusion avec proposition d'échange.\n- Utilise UNIQUEMENT les expériences et compétences présentes dans le profil. N'invente rien (ni chiffre, ni diplôme, ni expérience).\n- Pas d'en-tête d'adresse : commence par « Madame, Monsieur, » et termine par une formule de politesse et le nom du candidat.\n\nRéponds UNIQUEMENT avec un objet JSON valide :\n{\n  \"subject\": \"Objet de la candidature\",\n  \"letter\": \"Texte complet de la lettre, paragraphes séparés par \\n\\n\",\n  \"email\": \"Email court (60-90 mots) pour accompagner la candidature\",\n  \"tips\": [\"3 conseils concrets pour maximiser cette candidature\"]\n}";

return [{
  json: {
    job_id: j.id,
    llm_body: {
      temperature: 0.6,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        {
          role: 'user',
          content: [
            '### CANDIDAT',
            `Nom : ${p.full_name || ''}`,
            `Titre : ${p.headline || ''}`,
            `Compétences : ${list(p.skills)}`,
            `Expérience : ${p.years_experience ?? 'non précisé'} ans`,
            `CV :\n${(p.cv_text || 'non fourni').slice(0, 6000)}`,
            '',
            '### OFFRE',
            `Poste : ${j.title}`,
            `Entreprise : ${j.company || 'non précisée'}`,
            `Lieu : ${j.location || ''} · Contrat : ${j.contract_type || ''}`,
            `Compétences clés : ${list(j.key_skills)}`,
            `Points forts du candidat identifiés : ${list(j.strengths)}`,
            `Description :\n${(j.description || '').slice(0, 6000)}`,
          ].join('\n'),
        },
      ],
    },
  },
}];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parseLLM = (resp) => {
  if (resp?.error) throw new Error(resp.error.message || JSON.stringify(resp.error).slice(0, 300));
  const content = resp?.choices?.[0]?.message?.content;
  if (!content) throw new Error('Réponse vide du modèle IA');
  const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  return JSON.parse(clean);
};
// Telegram limite un message à 4096 caractères : on coupe proprement à la fin d'une ligne
const fit = (text, max = 3900) => {
  if (text.length <= max) return text;
  const cut = text.lastIndexOf('\n', max);
  return text.slice(0, cut > 0 ? cut : max) + '\n…';
};

const job = $('Offre et profil').first().json;
let r;
try {
  r = parseLLM($json);
  if (!r.letter) throw new Error('lettre absente de la réponse');
} catch (e) {
  return [{ json: { ok: false, chat_id: $env.TELEGRAM_CHAT_ID, text: `⚠️ La rédaction de la lettre a échoué (${esc(e.message)}). Réessaie avec /lettre_${job.id}.` } }];
}

const tips = (Array.isArray(r.tips) ? r.tips : []).slice(0, 3);
const fullText = [
  `Objet : ${r.subject || 'Candidature – ' + job.title}`,
  '',
  r.letter.trim(),
  '',
  '-----',
  'Email d\'accompagnement :',
  '',
  (r.email || '').trim(),
].join('\n');

const message = fit([
  `✍️ <b>Lettre pour « ${esc(job.title)} »</b>${job.company ? ' · ' + esc(job.company) : ''}`,
  '',
  `<b>Objet :</b> ${esc(r.subject || '')}`,
  '',
  esc(r.letter.trim()),
  '',
  '📧 <b>Email d\'accompagnement</b>',
  esc((r.email || '').trim()),
  ...(tips.length ? ['', '💡 <b>Conseils</b>', ...tips.map((t) => `• ${esc(t)}`)] : []),
].join('\n'));

const slug = String(job.company || job.title).toLowerCase().normalize('NFD').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40);
return [{
  json: {
    ok: true,
    job_id: job.id,
    url: job.url || 'https://francetravail.fr',
    chat_id: $env.TELEGRAM_CHAT_ID,
    text: message,
    full_text: fullText,
    file_name: `lettre-${slug || job.id}.txt`,
  },
}];

