WITH doc AS (
  INSERT INTO documents (job_id, kind, content) VALUES ($1::int, 'cover_letter', $2)
  RETURNING id
), shortlist AS (
  UPDATE jobs SET status = 'shortlisted' WHERE id = $1::int AND status = 'new' RETURNING id
)
SELECT (SELECT id FROM doc) AS document_id;
